  cut: '剪切', rename: '重命名', duplicate: '制作副本', retry: '重试',
  agent: '智能体', agents: '智能体', subagent: '子智能体', subagents: '子智能体',
  task: '任务', tasks: '任务', workspace: '工作区', workspaces: '工作区',
  directory: '目录', folder: '文件夹', file: '文件', files: '文件',
  command: '命令', commands: '命令', terminal: '终端', console: '控制台',
  output: '输出', input: '输入', error: '错误', warning: '警告', info: '信息',
